// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, uint256 v) public {
        address[] memory noTos = new address[](0);
        bool ok;
        try c.transfer(from, caddress, noTos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: with zero recipients the call must always revert.
        assertTrue(!ok, "empty recipient list must revert");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] memory tos, uint v) public {
        require(tos.length == 1);
        // caddress is this contract, which has no transferFrom function,
        // so the external call fails and P must revert.
        bool ok;
        try c.transfer(address(this), address(this), tos, v) { ok = true; } catch { ok = false; }
        assert(!ok);
    }
}

contract InvMutTest {
    C c;
    uint public callsMade;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        callsMade = 0;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        try c.transfer(from, address(this), _tos, v) {
            // no revert
        } catch {
            revert("P should not revert here");
        }
        assert(callsMade == _tos.length);
    }

    fallback() external payable {
        if (msg.sig == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            callsMade++;
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool called;
    address firstTo;
    address firstFrom;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v) public {
        require(_tos.length > 0);
        bool reverted;
        try c.transfer(from, address(this), _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted && called && firstTo == _tos[0] && firstFrom == from);
    }

    fallback(bytes calldata) external returns (bytes memory) {
        if (!called) {
            called = true;
            (, address to,) = abi.decode(msg.data[4:], (address, address, uint256));
            firstTo = to;
            firstFrom = abi.decode(msg.data[4:], (address));
        }
        return "";
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public {
        require(caddressIsSelf());
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool reverted;
        // call target is address(this), which lacks a transferFrom fallback, so the external call fails in P
        try c.transfer(from, address(this), tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    function caddressIsSelf() internal pure returns (bool) { return true; }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address[] memory tos, uint v, address laterRecipient) public payable {
        require(tos.length >= 2);
        require(tos[0] == address(this));
        require(laterRecipient != address(this));
        tos[1] = laterRecipient;
        bool reverted; try c.transfer(from, token, tos, v) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
